head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;
scwin.prevRow = -1;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 지표 표준코드 관리를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    dts_List.removeAll();

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }
    fn_CtrlBtn_temp("update");
    if (document.getElementById("btn_createstdcd")) {
        btn_createstdcd.setDisabled(true); // 표준코드등록
        btn_createstdcd.setBackgroundImage("../img/ins/btn_createstdcd_d.gif");
    }
    txb_STD_CD.setReadOnly(true);
    txb_STD_CD.setStyle("backgroundcolor", "#b9d4f7");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name new
 * @description 조회버튼 클릭시 신규등록을 위한 dataset 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_List.insertRow();
    fn_CtrlBtn_temp("insert");
    if (document.getElementById("btn_createstdcd")) {
        btn_createstdcd.setDisabled(false); // 표준코드등록
        btn_createstdcd.setBackgroundImage("../img/ins/btn_createstdcd.gif");
    }
    img_ISUR_CD.setDisabled(false);
    img_ISUR_CD.setBackgroundImage("../img/btn_search.gif");

    // txb_STD_CD.readOnly = false;
    // txb_STD_CD.style.background='white';

    cmb_ACTIV_TP_CD.setValue("Y");
};

/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function() {
    if (txb_ISUR_CD.getValue() === "" || txb_ISUR_CD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISUR_CD.getValue().length !== 5) {
        await $c.win.alert("올바른 지표발행기관코드 넣어주세요");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_ACTIV_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
        cmb_ACTIV_TP_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (txb_CFI_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI코드"));
        txb_CFI_CD.focus();
        return false;
    }
};

/**
 * @method
 * @name ins_register
 * @description 지표 표준코드 관리 등록전 표준코드 체크 한다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_register = async function() {
    if (await scwin.formCheck() === false) {
        return;
    }
    dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_stdcd.KeyName = "toinb_dataid4";
    // [전환검토] trs_stdcd.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_stdcd",
        action : "/StdCdIndcInfoAction.do",
        ref : "dts_stdcd,dts_List",
        target : "trs_stdcd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_register_insert
 * @description 지표 표준코드 관리 등록 한다. screenProcsTpCd 03
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_register_insert = async function() {
    dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    if (await scwin.formCheck() === false) {
        return;
    }
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/StdCdIndcInfoAction.do",
        ref : "dts_Rst,dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_modify
 * @description 지표 표준코드 관리를 수정 한다. screenProcsTpCd 03
 * @param {String} mflag mflag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function(mflag) {
    const screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        if (txb_ISUR_CD.getValue().length !== 5) {
            await $c.win.alert("올바른 지표발행기관코드 넣어주세요");
            txb_ISUR_CD.focus();
            return false;
        }
        if (cmb_ACTIV_TP_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
            cmb_ACTIV_TP_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
            txb_ISU_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (mflag === "N") return;
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/StdCdIndcInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정 - 채권과 동일 .....
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "T";
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setCfiFisn
 * @description cfi 변경시 fisn 셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCfiFisn = function() {
    let ISUR_CD = txb_ISUR_CD.getValue();
    ISUR_CD = ISUR_CD.substring(0, 2);
    let fisn1 = "";
    let fisn2 = "";
    if (ISUR_CD === "01") {
        fisn1 = "BOK";
        fisn2 = "KRW";
    } else if (ISUR_CD === "02") {
        fisn1 = "KRX";
        fisn2 = "Idx KR";
    } else if (ISUR_CD === "03") {
        // 사용안함

    } else if (ISUR_CD === "04") {
        // 사용안함

    }

    // fisn입력
    txb_fisn1.setValue(fisn1);
    txb_fisn2.setValue(fisn2);
};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    // cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, "ULDINS15900.xml", SCREN_PROCS_TP_CD_01, "18", "T", "", "", "G");
    // hidden패널
    // showObj(panel_12,false);

    txb_pSTD_CD.setValue("KRD");
    img_ISUR_CD.setDisabled(true);
    img_ISUR_CD.setBackgroundImage("../img/btn_search_d.gif");
    txb_pSTD_CD.focus();
};

/**
 * @method
 * @name btn_prcnm_onclick
 * @description 「처리자조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드
    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};

/**
 * @method
 * @name txb_pSTD_CD_onkeyup
 * @description txb_pSTD_CD 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_pSTD_CD_onkeyup = async function() {
    fn_DelChar(this);
    if (txb_pSTD_CD.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            await scwin.ins_search();
        } else {

        }
    }
};

/**
 * @method
 * @name txb_pISU_NM_onkeyup
 * @description txb_pISU_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_pISU_NM_onkeyup = async function() {
    fn_DelChar3(this);
    if (txb_pISU_NM.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            await scwin.ins_search();
        } else {

        }
    }
};

/**
 * @method
 * @name btn_createstdcd_onclick
 * @description 「표준코드등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_createstdcd_onclick = async function() {
    await scwin.ins_register();
};

/**
 * @method
 * @name btn_new_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_new_onclick = async function() {
    await scwin.new();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        let CFI_CD = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
        if (CFI_CD !== undefined) {
            scwin.setChange(CFI_CD);
        }
    }
    scwin.cnt = rowcount;

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
    scwin.cnt = 0;

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    await scwin.ins_search();
};

/**
 * @method
 * @name img_ISUR_CD_onclick
 * @description img_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS91400", "발행기관 코드", "570", "430");
    // cfi fisn 초기화
    txb_CFI_CD.setValue("");
    txb_fisn1.setValue("");
    txb_fisn2.setValue("");
    scwin.setChange("");
};

/**
 * @method
 * @name img_pISUR_CD_onclick
 * @description img_pISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pISUR_CD_onclick = function() {
    ins_popupOpen(txb_pISUR_CD, "", "ULDINS91400", "발행기관 코드", "570", "430");
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    if (await scwin.ins_modify("N") === false) return;
    ins_popupOpen("", "", "ULDINS93900", "수정사유", "470", "190");
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "지표 표준코드 관리 "));
    await scwin.ins_search();
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) === 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    img_ISUR_CD.setDisabled(true);
    img_ISUR_CD.setBackgroundImage("../img/btn_search_d.gif");
