/**
 * @method
 * @name dts_stdcd_OnLoadCompleted
 * @description 발행기관 등록후 결과값을 받아 처리한다.
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_stdcd_OnLoadCompleted = async function(rowcount) {
    // 발행기관 등록후 결과값을 받아 처리한다.
    let RESULT_CONTN = dts_stdcd.getCellData(0, "RESULT_CONTN");
    const r = confirm("표준코드 : " + RESULT_CONTN + " 등록하시겠습니까?");
    if (r === 1) {
        txb_STD_CD.setValue(RESULT_CONTN);
        await scwin.ins_register_insert();
    } else {
        txb_STD_CD.setValue("");
    }
};

