/**
 * @method
 * @name txb_ISU_NM_onkeyup
 * @description txb_ISU_NM 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_NM_onkeyup = function() {
    /*
1) 통화 : TCNXXX 01
2) 상품 : MRTXXX 04
3) 금리 : MRRXXX 03
4) 지수 : TIEXXX 02
     */
    if (txb_CFI_CD.getValue() === "") {
        let ISUR_CD = txb_ISUR_CD.getValue();
        ISUR_CD = ISUR_CD.substring(0, 2);
        //    alert(ISUR_CD);
        let cfi = "";
        let fisn1 = "";
        let fisn2 = "";
        if (ISUR_CD === "01") {
            cfi = "TCNXXX";
            fisn1 = "BOK";
            fisn2 = "KRW";
        } else if (ISUR_CD === "02") {
            cfi = "TIEXXX";
            fisn1 = "KRX";
            fisn2 = "Idx KR";
        } else if (ISUR_CD === "03") {
            // 사용안함
            cfi = "MRRXXX";
        } else if (ISUR_CD === "04") {
            // 사용안함
            cfi = "MRTXXX";
        }
        txb_CFI_CD.setValue(cfi);
        scwin.setChange(cfi);

        // fisn입력
        txb_fisn1.setValue(fisn1);
        txb_fisn2.setValue(fisn2);
    }
};

